/**
 * Generates shared/types.ts from the JSON Schemas in shared/.
 * Run with `npm run gen:types` (Node 24 strips the types itself).
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile, type JSONSchema } from 'json-schema-to-typescript';

export const SHARED_DIR = resolve(dirname(fileURLToPath(import.meta.url)), '../../shared');
export const TYPES_PATH = join(SHARED_DIR, 'types.ts');

const HEADER = `/* eslint-disable */
// GENERATED by \`npm run gen:types\` (extension/scripts/gen-types.ts) from shared/*.schema.json.
// Do not edit by hand: change the schema and regenerate.
`;

export async function generateTypes(): Promise<string> {
  const files = (await readdir(SHARED_DIR)).filter((f) => f.endsWith('.schema.json')).sort();
  const parts: string[] = [];
  for (const file of files) {
    const schema = JSON.parse(await readFile(join(SHARED_DIR, file), 'utf8')) as JSONSchema;
    const ts = await compile(schema, schema.title ?? file, {
      bannerComment: `// ---- ${file} (${schema.$id}) ----`,
      cwd: SHARED_DIR,
      additionalProperties: false,
      unreachableDefinitions: false,
      strictIndexSignatures: true,
    });
    parts.push(ts.trim());
  }
  return `${HEADER}\n${parts.join('\n\n')}\n`;
}

if ((import.meta as { main?: boolean }).main) {
  await writeFile(TYPES_PATH, await generateTypes());
  console.log(`Wrote ${TYPES_PATH}`);
}
